changeSet.sql:
CREATE UNIQUE INDEX uq_cash_registers_fm_fiscal_card_id
    ON cash_registers (LOWER(TRIM(fiscal_card_id)))
    WHERE fiscal_card_id IS NOT NULL AND TRIM(fiscal_card_id) <> '';
CREATE UNIQUE INDEX uq_cr_multikassa_fm_terminal_id
    ON cash_register_multikassa_settings (LOWER(TRIM(terminal_id)))
    WHERE terminal_id IS NOT NULL AND TRIM(terminal_id) <> '';
CREATE UNIQUE INDEX uq_cr_multikassa_fm_module_number
    ON cash_register_multikassa_settings (LOWER(TRIM(module_number)))
    WHERE module_number IS NOT NULL AND TRIM(module_number) <> '';
CREATE UNIQUE INDEX uq_cr_multikassa_fm_selected_drive_id
    ON cash_register_multikassa_settings (LOWER(TRIM(selected_drive_id)))
    WHERE selected_drive_id IS NOT NULL AND TRIM(selected_drive_id) <> '';
CREATE UNIQUE INDEX uq_cr_fiscal_drive_fm_factory_id
    ON cash_register_fiscal_drive_settings (LOWER(TRIM(factory_id)))
    WHERE factory_id IS NOT NULL AND TRIM(factory_id) <> '';
CREATE UNIQUE INDEX uq_cr_fiscal_drive_fm_terminal_id
    ON cash_register_fiscal_drive_settings (LOWER(TRIM(terminal_id)))
    WHERE terminal_id IS NOT NULL AND TRIM(terminal_id) <> '';

changeSet.rollback:
DROP INDEX IF EXISTS uq_cash_registers_fm_fiscal_card_id;
DROP INDEX IF EXISTS uq_cr_multikassa_fm_terminal_id;
DROP INDEX IF EXISTS uq_cr_multikassa_fm_module_number;
DROP INDEX IF EXISTS uq_cr_multikassa_fm_selected_drive_id;
DROP INDEX IF EXISTS uq_cr_fiscal_drive_fm_factory_id;
DROP INDEX IF EXISTS uq_cr_fiscal_drive_fm_terminal_id;
